 public static bool ShouldStayInTray(CloseReason reason,bool wallpaperEnabled,bool explicitExit,bool testing){return reason==CloseReason.UserClosing&&wallpaperEnabled&&!explicitExit&&!testing;}
 void HandleClosing(object sender,FormClosingEventArgs e){if(ShouldStayInTray(e.CloseReason,F.S.WallpaperEnabled,exitRequested,Testing)){e.Cancel=true;desktop=true;F.S.Desktop=true;Hide();SaveGame();RuntimeLog.Write("Management window hidden; wallpaper remains active");}else{SaveGame();if(!Testing)RuntimeLog.Write("Exiting: "+e.CloseReason+"; explicit="+exitRequested);}}
 public void ExitGame(){exitRequested=true;Close();}
 public string CurrentPanel {get{return panel;}}public bool DesktopMode {get{return desktop;}}
 void Frame(){if(disposed)return;EnsureShortcut();if(Program.QuitSignal!=null&&Program.QuitSignal.WaitOne(0)){ExitGame();return;}if(Program.DesktopSignal!=null&&Program.DesktopSignal.WaitOne(0))SetDesktop(true);if(Program.OpenSignal!=null&&Program.OpenSignal.WaitOne(0))ExpandWindow();if(awaitingDesktop){if(engineHost!=null&&engineHost.DesktopReady){awaitingDesktop=false;Hide();}else if((DateTime.UtcNow-desktopRequested).TotalSeconds>30){awaitingDesktop=false;desktop=false;Show();Toast("桌面连接尚未完成，请点击设为桌面背景重试。");}}double now=F.Now;animation+=(DateTime.Now-lastFrame).TotalSeconds;lastFrame=DateTime.Now;F.Tick();if(F.Notices.Count>0){Toast(F.Notices.Last());F.Notices.Clear();}if(now-lastSave>15){SaveGame();lastSave=now;}timer.Interval=!Visible?250:F.S.Quiet?240:80;if(Visible)Invalidate();if(engineHost!=null)engineHost.Pulse();else if(!Testing&&F.S.WallpaperEnabled&&now>nextWallpaperAttempt){nextWallpaperAttempt=now+5;if(EnsureWallpaper()&&F.S.Desktop){desktop=true;Hide();}}}
 public void SaveGame(){if(Testing)return;try{F.Save(SavePath);saveFailed=false;}catch(Exception e){if(!saveFailed){toast="存档暂时写入失败："+e.Message;toastUntil=F.Now+15;}saveFailed=true;}}
 void Toast(string message){toast=message;toastUntil=F.Now+6;}
 void Act(Func<string> f,string sound="click"){Toast(f());SaveGame();Play(sound);Invalidate();}
 void Open(string name){if(desktop){SetDesktop(false);}panel=name;page=0;tab="";placement=null;decorMove=-1;Invalidate();}
