 void UpdateLabels(){Text=L.T("Mosslight · 苔光桌面农场");AccessibleName=Text;tray.Text=L.T("苔光农场 · 安心忙碌，慢慢生长");var old=tray.ContextMenuStrip;var menu=new ContextMenuStrip();menu.Items.Add(L.T("打开农场"),null,(sender,e)=>ExpandWindow());menu.Items.Add(L.T("设为桌面背景"),null,(sender,e)=>SetDesktop(true));menu.Items.Add(L.T("布置桌面"),null,(sender,e)=>ShowWallpaperPreview());menu.Items.Add(L.T("恢复原桌面"),null,(sender,e)=>StopWallpaper());menu.Items.Add(L.T("修复桌面"),null,(sender,e)=>{if(engineHost!=null)engineHost.RequestRepair(true);else SetDesktop(true);});menu.Items.Add("中文 / English",null,(sender,e)=>ToggleLanguage());menu.Items.Add(L.T("保存并退出"),null,(sender,e)=>ExitGame());tray.ContextMenuStrip=menu;if(old!=null)old.Dispose();}
 void ToggleLanguage(){F.S.Language=F.S.Language=="en"?"zh-CN":"en";L.SetLanguage(F.S.Language);F.S.Language=L.Code;UpdateLabels();SaveGame();Toast("语言已切换，存档进度保持不变。");Invalidate();if(wallpaper!=null)wallpaper.Invalidate();if(wallpaperPreview!=null)wallpaperPreview.Invalidate();}
 bool EnsureWallpaper(){if(!Testing&&!NativeDesktop.RuntimeAvailable){F.S.WallpaperEnabled=false;F.S.Desktop=false;SaveGame();if(!runtimePrompted){runtimePrompted=true;MessageBox.Show(L.T("需要免费的 Microsoft WebView2 显示组件。请运行游戏文件夹内 runtime/MicrosoftEdgeWebview2Setup.exe，安装完成后再次点击设为桌面背景。"),"Mosslight");}return false;}if(engineHost!=null&&engineHost.Active)return true;if(!Testing){try{engineHost=new LiveFarmHost(this,F,()=>{UpdateLabels();SaveGame();},name=>{ExpandWindow();if(name!="")Open(name);},SavePath);engineHost.Start();return true;}catch(Exception e){if(engineHost!=null){engineHost.Dispose();engineHost=null;}Toast("动态壁纸连接失败："+e.Message);return false;}}Toast("请先运行 Wallpaper Engine，再启用动态农场壁纸。");return false;}
 public void SetDesktop(bool enabled){panel="";placement=null;decorMove=-1;if(enabled){if(!EnsureWallpaper()){desktop=false;Show();Activate();return;}F.S.WallpaperEnabled=true;F.S.Desktop=true;desktop=true;SaveGame();desktopRequested=DateTime.UtcNow;awaitingDesktop=true;engineHost.RequestRepair(true);Toast("正在连接互动桌面，请稍候。");}else{desktop=false;F.S.Desktop=false;Show();WindowState=FormWindowState.Normal;Activate();SaveGame();}Invalidate();}
 void StopWallpaper(){if(engineHost!=null){engineHost.Dispose();engineHost=null;}if(wallpaper!=null){wallpaper.Close();wallpaper=null;}F.S.WallpaperEnabled=false;F.S.Desktop=false;desktop=false;ExpandWindow();Act(()=>"已恢复原来的桌面背景。");}
