 bool FreeSpot(Point p,int skip){if(p.X<61||p.X>542||p.Y<158||p.Y>273)return false;if(new Rectangle(212,128,168,150).Contains(p)||new Rectangle(69,111,110,99).Contains(p)||new Rectangle(386,100,76,111).Contains(p)||new Rectangle(443,195,116,83).Contains(p)||new Rectangle(49,207,72,64).Contains(p)||new Rectangle(140,214,63,67).Contains(p)||new Rectangle(389,224,57,56).Contains(p))return false;for(int i=0;i<F.S.Decorations.Count;i++)if(i!=skip){var d=F.S.Decorations[i];if(Math.Abs(d.X-p.X)<22&&Math.Abs(d.Y-p.Y)<19)return false;}return true;}
 int PlotAt(Point p){return -1;}
 void WorldClick(Point p){if(placement!=null){if(!FreeSpot(p,-1)){Toast("这里留给田地、建筑或道路吧。换一块空闲草地。");return;}string kind=placement;int count=F.S.Decorations.Count;Act(()=>F.BuyDecoration(kind,p.X,p.Y));if(F.S.Decorations.Count>count)placement=null;return;}if(decorMove>=0){if(!FreeSpot(p,decorMove)){Toast("这处位置放不下装饰，请换一块草地。");return;}if(decorMove<F.S.Decorations.Count){F.S.Decorations[decorMove].X=p.X;F.S.Decorations[decorMove].Y=p.Y;}decorMove=-1;SaveGame();Toast("装饰已移动。");return;}
 int plot=PlotAt(p);if(plot>=0){if(plot>=F.S.Plots.Count){Open("build");Toast("还未开垦的土地，可以在这里扩建。");return;}var crop=F.S.Plots[plot];if(crop.Crop=="")Act(()=>F.Plant(plot,selected));else if(crop.Ready<=F.Now)Act(()=>F.Harvest(plot),"harvest");else if(watering)Act(()=>F.Water(plot),"water");else Toast(Farm.ItemName(crop.Crop)+" · "+Farm.TimeText(crop.Ready-F.Now)+"后成熟"+(crop.Watered?" · 已浇水":" · 按 W 可切换浇水"));return;}
 var pet=PixelArt.PetPosition(animation);if(Math.Abs(p.X-pet.X)<20&&Math.Abs(p.Y-pet.Y)<25){Act(F.Pet);return;}for(int i=F.S.Decorations.Count-1;i>=0;i--){var d=F.S.Decorations[i];if(Math.Abs(p.X-d.X)<16&&p.Y>=d.Y-(d.Type=="tree"?60:25)&&p.Y<=d.Y+8){decorMove=i;if(desktop)SetDesktop(false);Toast("点击空闲草地移动装饰；Esc 取消。");return;}}
 if((F.Has("dairy")&&new Rectangle(263,71,43,48).Contains(p))||(F.Has("loom")&&new Rectangle(205,66,43,48).Contains(p))||(F.Has("sugarhouse")&&new Rectangle(321,71,43,48).Contains(p))||(F.Has("preserves")&&new Rectangle(478,119,43,48).Contains(p))){Open("workshop");if(p.X<252||p.X>315)page=1;return;}if(F.Has("bakery")&&new Rectangle(39,178,80,88).Contains(p)){Open("workshop");return;}if(new Rectangle(387,93,74,110).Contains(p)){Open("workshop");return;}if(new Rectangle(72,105,108,96).Contains(p)){Open("journal");return;}if(p.X<206&&p.Y>213){Open(F.Has("coop")?"pet":"build");return;}if(p.X>390&&p.X<443&&p.Y>226){Open(F.Has("barn")?"pet":"build");return;}Toast("让风车慢慢转，今天也慢慢来。");}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);mouseLogical=new Point((int)(e.X*(desktop?600.0:1200)/ClientSize.Width),(int)(e.Y*(desktop?360.0:800)/ClientSize.Height));mouseWorld=desktop?mouseLogical:new Point(mouseLogical.X/2,(mouseLogical.Y-78)/2);hoverPlot=panel==""?PlotAt(mouseWorld):-1;tip="";foreach(var h in hits)if(h.Bounds.Contains(mouseLogical)&&h.Hint!="")tip=h.Hint;Cursor=(hoverPlot>=0||hits.Any(h=>h.Bounds.Contains(mouseLogical)))?Cursors.Hand:Cursors.Default;}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);OnMouseMove(e);if(e.Button==MouseButtons.Right&&panel==""){for(int i=F.S.Decorations.Count-1;i>=0;i--){var d=F.S.Decorations[i];if(Math.Abs(mouseWorld.X-d.X)<16&&Math.Abs(mouseWorld.Y-d.Y)<25){F.S.Coins+=Farm.DecorCost(d.Type)/2;F.S.Decorations.RemoveAt(i);decorMove=-1;Act(()=>"装饰已收回，返还一半金币。","coin");return;}}watering=!watering;Toast(watering?"浇水工具已选中。":"切回种植工具。");return;}if(e.Button!=MouseButtons.Left)return;for(int i=hits.Count-1;i>=0;i--)if(hits[i].Bounds.Contains(mouseLogical)){var action=hits[i].Action;action();Invalidate();return;}}
 protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Escape){if(panel=="welcome"){F.S.IntroSeen=true;SaveGame();}panel="";placement=null;decorMove=-1;Invalidate();return;}if(panel!="")return;if(e.KeyCode>=Keys.D1&&e.KeyCode<=Keys.D9){int i=(int)e.KeyCode-(int)Keys.D1;if(F.Level>=Farm.Crops[i].Level){selected=Farm.Crops[i].Id;F.S.SelectedSeed=selected;SaveGame();watering=false;Toast("已选择"+Farm.Crops[i].Name);}}if(e.KeyCode==Keys.H)Act(F.HarvestAll,"harvest");if(e.KeyCode==Keys.W){watering=!watering;Toast(watering?"已选择浇水工具。":"已选择种植工具。");}if(e.KeyCode==Keys.B)Open("inventory");if(e.KeyCode==Keys.O)Open("orders");Invalidate();}
 void Play(string name){if(!F.S.Sound||F.S.Music)return;try{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",name+".wav");if(!File.Exists(path))return;if(!sounds.ContainsKey(name))sounds[name]=new SoundPlayer(path);sounds[name].Play();}catch{}}
 void SetMusic(bool on){try{if(musicPlayer!=null){musicPlayer.Stop();musicPlayer.Dispose();musicPlayer=null;}if(on){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","meadow.wav");if(File.Exists(path)){musicPlayer=new SoundPlayer(path);musicPlayer.PlayLooping();}}}catch{Toast("音乐暂时无法播放。");}}
 protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;if(engineHost!=null){engineHost.Dispose();engineHost=null;}timer.Stop();timer.Dispose();if(wallpaper!=null){wallpaper.Close();wallpaper=null;}if(wallpaperPreview!=null){wallpaperPreview.Close();wallpaperPreview=null;}UnregisterHotKey(Handle,1);tray.Visible=false;tray.Dispose();if(musicPlayer!=null){musicPlayer.Stop();musicPlayer.Dispose();}foreach(var s in sounds.Values)s.Dispose();foreach(var f in fonts.Values)f.Dispose();ownIcon.Dispose();}base.Dispose(disposing);}
}
